CREATE TABLE IF NOT EXISTS work_tasks(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),activity_id TEXT REFERENCES customer_activities(id),title TEXT NOT NULL,description TEXT,assignee_id TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id),priority TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'todo',due_date TEXT,completed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS task_events(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES work_tasks(id),actor_id TEXT NOT NULL REFERENCES users(id),event TEXT NOT NULL,details TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS workflow_runs(id TEXT PRIMARY KEY,rule TEXT NOT NULL,entity_id TEXT NOT NULL,executed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(rule,entity_id,executed_at));